  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "A close benzimidazole-piperidine analogue (9q) had a brain/plasma ratio of 2.7 and CNS exposure equivalent to known sedating antihistamines after IV dosing, directly supporting brain penetration of the query's core scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A piperidine-linked heteroaryl analogue with an ether-containing N-substituent reached a rat brain Cmax of 234 ng/g and was labeled permeable, supporting CNS access for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A benzimidazole-containing compound reached 13 µM in rat brain 30 min after IP dosing, demonstrating that benzimidazole-based analogues in this series achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "PET imaging in baboons showed rapid brain localization of a piperidine-benzimidazolone antipsychotic, supporting CNS penetration of the piperidine-benzimidazole class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "In vivo rat studies with [11C]SA4503 showed high and receptor-specific brain uptake, supporting that lipophilic basic amine scaffolds of this type cross the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the benzimidazole-piperidine scaffold is consistently brain-penetrant across multiple in vivo, PET, and PK records. The query's terminal carboxylic acid introduces some uncertainty, but the strong transferable scaffold evidence supports meaningful CNS access.",
